"""Tauri 2 Windows applications with complete static frontend and Rust inputs."""
import json
from catalog_support import Book
from expansion_support import save_book

def js(value):return json.dumps(value,ensure_ascii=False,indent=2)+"\n"
BUILD='''fn u16le(out:&mut Vec<u8>,value:u16){out.extend(value.to_le_bytes());}
fn u32le(out:&mut Vec<u8>,value:u32){out.extend(value.to_le_bytes());}
fn icon()->Vec<u8>{let mut dib=Vec::new();u32le(&mut dib,40);u32le(&mut dib,32);u32le(&mut dib,64);u16le(&mut dib,1);u16le(&mut dib,32);u32le(&mut dib,0);u32le(&mut dib,4096);for _ in 0..4{u32le(&mut dib,0);}for y in 0..32{for x in 0..32{let mark=(12..20).contains(&x)||(12..20).contains(&y);dib.extend(if mark{[245u8,245,245,255]}else{[145,73,40,255]});}}dib.extend([0u8;128]);let mut ico=Vec::new();u16le(&mut ico,0);u16le(&mut ico,1);u16le(&mut ico,1);ico.extend([32u8,32,0,0]);u16le(&mut ico,1);u16le(&mut ico,32);u32le(&mut ico,dib.len()as u32);u32le(&mut ico,22);ico.extend(dib);ico}
fn main(){std::fs::create_dir_all("icons").expect("icons directory");std::fs::write("icons/icon.ico",icon()).expect("icon write");tauri_build::build();}
'''
CARGO='''[package]
name="atlas_tauri"
version="1.0.0"
edition="2021"
rust-version="1.90"
[build-dependencies]
tauri-build="=2.7.3"
[dependencies]
tauri="=2.12.4"
serde={version="1.0",features=["derive"]}
serde_json="1.0"
'''
HTML='''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laboratorio Tauri</title><link rel="stylesheet" href="style.css"></head><body><main><h1>Laboratorio Tauri</h1><label>Valore <input id="input" value="4"></label><button id="run">Esegui</button><pre id="result" role="status"></pre></main><script src="main.js"></script></body></html>
'''
STYLE="body{font:16px system-ui;margin:32px;background:#142338;color:#edf4ff}button,input{font:inherit;padding:10px;margin:8px}pre{white-space:pre-wrap}button:focus-visible,input:focus-visible{outline:3px solid #70d5dc}"
DEFAULT='''#[tauri::command]
fn demo()->String{"Ponte Rust pronto".into()}
'''

def tauri_files(key,rust=DEFAULT,operation="return await api.core.invoke('demo');",permissions=None,setup='',imports='',extra=None,frontend=None):
    config={"$schema":"https://schema.tauri.app/config/2","productName":"AtlasTauri","version":"1.0.0","identifier":"it.atlas.tauri."+key.replace('-',''),"build":{"frontendDist":"../web"},"app":{"withGlobalTauri":True,"windows":[{"label":"main","title":"Laboratorio Tauri","width":760,"height":520}],"security":{"csp":"default-src 'self'; script-src 'self'; style-src 'self'; connect-src ipc: http://ipc.localhost; object-src 'none'"}},"bundle":{"active":True,"targets":["nsis"],"icon":["icons/icon.ico"]}}
    main='#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]\nuse tauri::Manager;\n'+imports+'\n'+rust+'\nfn main(){tauri::Builder::default()'+setup+'.invoke_handler(tauri::generate_handler![demo]).run(tauri::generate_context!()).expect("Tauri application failed");}\n'
    client="const output=document.querySelector('#result'),input=document.querySelector('#input');const api=window.__TAURI__;document.querySelector('#run').addEventListener('click',async()=>{try{if(!api)throw new Error('Avvia tramite tauri dev, non con un browser statico');const result=await (async()=>{"+operation+"})();output.textContent=JSON.stringify(result,null,2);}catch(error){output.textContent=String(error);}});\n"
    return {"package.json":js({"name":"atlas-tauri-example","version":"1.0.0","private":True,"scripts":{"tauri":"tauri","dev":"tauri dev","build":"tauri build --no-bundle"},"devDependencies":{"@tauri-apps/cli":"2.12.4"}}),"src-tauri/Cargo.toml":CARGO,"src-tauri/build.rs":BUILD,"src-tauri/tauri.conf.json":js(config),"src-tauri/capabilities/main.json":js({"identifier":"main-capability","description":"Permessi della sola finestra locale main","windows":["main"],"permissions":["core:default",*(permissions or [])]}),"src-tauri/src/main.rs":main,"web/index.html":HTML,"web/style.css":STYLE,"web/main.js":frontend or client,**(extra or {})}

ROWS=[
('greet','Passare una stringa dal frontend a Rust','Invocare un comando tipizzato mantenendo HTML e logica nativa separati.','#[tauri::command]fn demo(name:String)->String{format!("Ciao {}",name.trim())}',"return await api.core.invoke('demo',{name:input.value});",'La risposta contiene il nome passato dal campo.'),
('checked-number','Proteggere un calcolo da overflow','Usare checked_mul e convertire il fallimento in Result serializzabile.','#[tauri::command]fn demo(value:i64)->Result<i64,String>{value.checked_mul(value).ok_or_else(||"Overflow".into())}',"const value=Number(input.value);if(!Number.isSafeInteger(value))throw new Error('Intero richiesto');return await api.core.invoke('demo',{value});",'4 restituisce16; valori troppo grandi vengono rifiutati.'),
('validation','Rifiutare argomenti non validi nel backend','Mantenere la validazione nel comando anche quando il frontend esegue un controllo.','#[tauri::command]fn demo(value:i64)->Result<String,String>{if !(1..=100).contains(&value){return Err("Valore ammesso:1..100".into())}Ok(format!("Valore valido:{}",value))}',"return await api.core.invoke('demo',{value:Number(input.value)});",'Il backend accetta solo interi da1 a100.'),
('dto','Restituire un oggetto Serde al frontend','Derivare Serialize e lasciare a Tauri la codifica JSON.','#[derive(serde::Serialize)]struct Summary{name:String,quantity:u32}#[tauri::command]fn demo()->Summary{Summary{name:"Keyboard".into(),quantity:8}}',"return await api.core.invoke('demo');",'Il frontend riceve un oggetto con name e quantity.'),
('state','Conservare stato condiviso tra invocazioni','Registrare un Mutex gestito dal builder e mantenere il lock per il solo aggiornamento.','#[derive(Default)]struct Counter(std::sync::Mutex<u32>);#[tauri::command]fn demo(state:tauri::State<Counter>)->Result<u32,String>{let mut value=state.inner().0.lock().map_err(|_|"Lock non disponibile")?;*value+=1;Ok(*value)}',"return await api.core.invoke('demo');",'I clic successivi restituiscono1,2,3 nella sessione.',[],'.manage(Counter::default())'),
('async','Spostare un calcolo fuori dal thread principale','Usare spawn_blocking per lavoro CPU evitando di bloccare il ciclo eventi nativo.','#[tauri::command]async fn demo()->Result<u64,String>{tauri::async_runtime::spawn_blocking(||(0u64..10000).map(|n|n*n).sum()).await.map_err(|error|error.to_string())}',"return await api.core.invoke('demo');",'La somma arriva tramite Promise senza un blocco esplicito del thread UI.'),
('events','Inviare un evento da Rust alla finestra','Registrare il listener prima di chiamare il comando e rimuoverlo dopo la risposta.','#[tauri::command]fn demo(app:tauri::AppHandle)->Result<(),String>{use tauri::Emitter;app.emit("atlas-ready","Evento da Rust").map_err(|error|error.to_string())}',"return await new Promise(async(resolve,reject)=>{let stop=()=>{};const timer=setTimeout(()=>{stop();reject(new Error('Evento non ricevuto'));},3000);try{stop=await api.event.listen('atlas-ready',event=>{clearTimeout(timer);stop();resolve(event.payload);});await api.core.invoke('demo');}catch(error){clearTimeout(timer);stop();reject(error);}});",'L’evento èricevuto e il listener viene rilasciato anche su timeout.'),
('window-title','Aggiornare il titolo della finestra','Dichiarare il permesso minimo richiesto dalla API nativa.',DEFAULT,"await api.window.getCurrentWindow().setTitle(input.value);return 'Titolo aggiornato';",'Il titolo cambia al valore del campo.',['core:window:allow-set-title']),
('window-size','Ridimensionare in unità logiche','Distinguere dimensioni logiche da pixel fisici su schermi con DPI differenti.',DEFAULT,"await api.window.getCurrentWindow().setSize(new api.dpi.LogicalSize(900,600));return 'Dimensione logica900×600';",'La finestra assume la dimensione logica richiesta.',['core:window:allow-set-size']),
('minimize','Minimizzare la finestra dal frontend','Usare la finestra corrente senza esporre comandi nativi generici.',DEFAULT,"await api.window.getCurrentWindow().minimize();return 'Minimizzata';",'La finestra viene minimizzata.',['core:window:allow-minimize']),
('fullscreen','Alternare schermo intero e finestra','Leggere lo stato corrente prima di scegliere la modifica.',DEFAULT,"const window=api.window.getCurrentWindow();await window.setFullscreen(!(await window.isFullscreen()));return 'Modalità alternata';",'Un secondo clic ripristina la modalità precedente.',['core:window:allow-set-fullscreen']),
('center','Centrare la finestra sul monitor','Delegare la posizione al sistema nativo anziché calcolare coordinate assolute.',DEFAULT,"await api.window.getCurrentWindow().center();return 'Finestra centrata';",'La finestra viene centrata.',['core:window:allow-center']),
('version','Leggere la versione distribuita dell’app','Interrogare il manifest Tauri invece di duplicare una stringa nel frontend.',DEFAULT,"return {name:await api.app.getName(),version:await api.app.getVersion()};",'Il frontend mostra AtlasTauri e1.0.0.'),
('scale','Leggere DPI e dimensioni effettive','Esaminare scala del monitor e dimensione interna fisica prima di fare conversioni.',DEFAULT,"const window=api.window.getCurrentWindow();return {scale:await window.scaleFactor(),physical:await window.innerSize()};",'La risposta riporta valori effettivi del monitor.'),
('close','Confermare una chiusura richiesta dall’utente','Far dipendere la chiusura da una scelta esplicita del frontend.',DEFAULT,"if(confirm('Chiudere questa finestra di laboratorio?'))await api.window.getCurrentWindow().close();return 'Operazione annullata o chiusura richiesta';",'Annulla conserva la finestra, conferma ne richiede la chiusura.',['core:window:allow-close']),
('app-data','Scrivere e rileggere un file nella cartella app','Ricavare una posizione specifica dell’app anziché usare il working directory.','#[tauri::command]fn demo(app:tauri::AppHandle)->Result<String,String>{let folder=app.path().app_data_dir().map_err(|e|e.to_string())?;std::fs::create_dir_all(&folder).map_err(|e|e.to_string())?;let file=folder.join("demo.txt");std::fs::write(&file,"Testo locale UTF-8").map_err(|e|e.to_string())?;std::fs::read_to_string(file).map_err(|e|e.to_string())}',"return await api.core.invoke('demo');",'Il testo viene riletto dallo spazio app con identificatore dedicato.'),
('json-parse','Validare una struttura JSON ricevuta come stringa','Usare Deserialize e rifiutare input incompatibile prima della logica applicativa.','#[derive(serde::Deserialize,serde::Serialize)]struct Item{name:String,qty:u32}#[tauri::command]fn demo(text:String)->Result<Item,String>{let item:Item=serde_json::from_str(&text).map_err(|e|e.to_string())?;if item.name.trim().is_empty(){return Err("Nome vuoto".into())}Ok(item)}',"return await api.core.invoke('demo',{text:input.value});",'Una stringa JSON con name e qty validi viene restituita come oggetto; gli altri input producono errore.'),
('structured-error','Restituire un errore strutturato al chiamante','Rappresentare codice e messaggio nel ramo Err usando una struttura serializzabile.','#[derive(serde::Serialize)]struct LabError{code:String,message:String}#[tauri::command]fn demo()->Result<String,LabError>{Err(LabError{code:"not_available".into(),message:"Risorsa dimostrativa non disponibile".into()})}',"try{return await api.core.invoke('demo');}catch(error){return {handled:true,error};}",'Il frontend può distinguere codice e messaggio dell’errore.'),
('filter-command','Filtrare risultati nel backend senza interpretare codice','Passare una query come dato e usare confronto case-insensitive.','#[tauri::command]fn demo(query:String)->Vec<String>{let query=query.to_lowercase();["Python","PostgreSQL","Rust"].into_iter().filter(|name|name.to_lowercase().contains(&query)).map(str::to_string).collect()}',"return await api.core.invoke('demo',{query:input.value});",'La query py restituisce Python.'),
]

def build_all():
    assert len(ROWS)==19,len(ROWS)
    book=Book('tauri','Tauri2.12.4;tauri-build2.7.3;Rust>=1.90;CLI2.12.4',["https://v2.tauri.app/start/prerequisites/","https://v2.tauri.app/develop/calling-rust/","https://v2.tauri.app/security/capabilities/"],"Windows x64 con RustMSVC1.90+, Visual Studio Desktop development with C++, Windows SDK e WebView2 Runtime. Node24 e npm per la CLI locale. Questi esempi producono Windows; non attestano build Linux/macOS/mobile.",os=['Windows'],ide=['VS Code'])
    lifecycle=[('setup','Inizializzare un’app Tauri con frontend statico','Inizializzazione','rustc --version\nnode --version\nnpm install\nnpm run dev','Il progetto comprende Cargo, build.rs, configurazione, capability e frontend. Non richiede Vite: frontendDist punta a web. withGlobalTauri espone il ponte specifico a questa UI locale. Il build script produce un’icona originale prima della fase risorse Windows.'),('build','Compilare l’eseguibile Tauri senza installer','Compilazione','npm install\nnpm run build','La build usa tauri build --no-bundle per controllare frontend e backend senza creare un installer. Il binario Release ènel target Cargo. Non presumere che lo stesso binario funzioni su altre architetture.'),('debug','Collegare il debugger Rust alla build Tauri','Debug','npm install\nnpm run dev','In VS Code installa rust-analyzer e un debugger Rust compatibile MSVC. In development gli strumenti WebView e i breakpoint Rust controllano lati differenti del ponte. La configurazione LLDB allegata avvia il binario Debug dopo una prima compilazione; una versione del debugger che non supporta MSVC va sostituita con gli strumenti Visual Studio.'),('test','Testare logica Rust senza avviare la WebView','Test','cargo test --manifest-path src-tauri/Cargo.toml','Il modulo cfg(test) verifica un calcolo puro. Non crea la finestra e non verifica permessi o rendering; per quelli serve una prova dell’app completa.'),('deploy','Generare un installer Windows Tauri NSIS','Distribuzione','npm install\nnpm run tauri -- build --bundles nsis','La configurazione targets nsis usa l’icona generata e include le risorse. Il bundler può dover ottenere i tool NSIS e il bootstrapper WebView2; la guida non attesta quel download né la firma. Prima di consegnare, installa in un Windows di prova e verifica dipendenze e disinstallazione.')]
    for key,title,section,command,guide in lifecycle:
        rust=DEFAULT
        if key=='test':rust='fn square(value:i64)->Option<i64>{value.checked_mul(value)}\n#[tauri::command]fn demo()->Option<i64>{square(4)}\n#[cfg(test)]mod tests{use super::*;#[test]fn squares(){assert_eq!(square(4),Some(16));assert_eq!(square(-3),Some(9));assert_eq!(square(i64::MAX),None);}}'
        data=tauri_files(key,rust)
        if key=='debug':data['.vscode/launch.json']=js({'version':'0.2.0','configurations':[{'type':'lldb','request':'launch','name':'Tauri Debug','program':'${workspaceFolder}/src-tauri/target/debug/atlas_tauri.exe','cwd':'${workspaceFolder}'}]})
        book.add(key,title,guide,data,section=section,commands=command,explanation='## Procedura\n'+guide+'\n\n## Prerequisiti\n'+book.prerequisites+'\n\n## File\nApri la radice con package.json. La cartella src-tauri contiene il crate; le permission riguardano soltanto la finestra main. L’icona viene generata da codice originale nel build script, quindi non manca un asset binario nascosto.',expected='Il risultato segue la procedura indicata quando la toolchain nativa richiesta èdisponibile.',tags=['tauri',key,'Rust','WebView2','Windows'])
    for row in ROWS:
        key,title,desc,rust,operation,expected,*rest=row
        permissions=rest[0] if rest else None;setup=rest[1] if len(rest)>1 else ''
        book.add(key,title,desc,tauri_files(key,rust,operation,permissions,setup),commands='npm install\nnpm run dev',explanation=f'## Ponte frontend/backend\n{desc}\n\n## Avvio\nEsporta tutta la struttura e avvia npm run dev dalla radice. Il pulsante esegue il codice in web/main.js; i comandi registrati sono in src-tauri/src/main.rs. Aprire index.html in un browser ordinario non fornisce il ponte Tauri.\n\n## Controllo\n{expected}\n\n## Permission\nLa capability della sola finestra main dichiara i permessi core necessari. I comandi applicativi accettano dati specifici; non espongono una shell o un percorso arbitrario. Gli esempi con file usano soltanto lo spazio della propria app.',expected=expected,tags=['tauri',key,'IPC','Rust','capability'])
    model='''#[derive(Clone,serde::Serialize,serde::Deserialize)]struct Task{id:u64,title:String,done:bool}
fn add(rows:&[Task],title:&str)->Result<Vec<Task>,String>{let title=title.trim();if title.is_empty()||title.chars().count()>200{return Err("Titolo non valido".into())}let next=rows.iter().map(|r|r.id).max().unwrap_or(0).checked_add(1).ok_or("ID esauriti")?;let mut out=rows.to_vec();out.push(Task{id:next,title:title.into(),done:false});Ok(out)}
struct Notes{rows:std::sync::Mutex<Vec<Task>>,file:std::path::PathBuf}
#[tauri::command]fn demo(title:String,state:tauri::State<Notes>)->Result<Vec<Task>,String>{let mut rows=state.rows.lock().map_err(|_|"Lock non disponibile")?;let next=add(&rows,&title)?;if let Some(parent)=state.file.parent(){std::fs::create_dir_all(parent).map_err(|e|e.to_string())?;}let temp=state.file.with_extension("tmp");std::fs::write(&temp,serde_json::to_vec_pretty(&next).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;std::fs::rename(&temp,&state.file).map_err(|e|e.to_string())?;*rows=next.clone();Ok(next)}
#[cfg(test)]mod tests{use super::*;#[test]fn empty(){assert!(add(&[]," ").is_err());}#[test]fn immutable_ids(){let old=vec![Task{id:4,title:"prima".into(),done:false}];let next=add(&old," seconda ").unwrap();assert_eq!(old.len(),1);assert_eq!(next[1].id,5);assert_eq!(next[1].title,"seconda");}#[test]fn long_title(){assert!(add(&[],&"a".repeat(201)).is_err());}}
'''
    setup='.setup(|app|{let file=app.path().app_data_dir()?.join("notes.json");let rows=if file.exists(){serde_json::from_slice::<Vec<Task>>(&std::fs::read(&file)?)?}else{Vec::new()};app.manage(Notes{rows:std::sync::Mutex::new(rows),file});Ok(())})'
    project=tauri_files('tasks',model,"return await api.core.invoke('demo',{title:input.value});",setup=setup)
    project['web/index.html']=HTML.replace('Valore','Titolo').replace('value="4"','value=""').replace('Esegui','Aggiungi e salva')
    project['README.md']='# Note Tauri\nRustMSVC1.90+, WebView2 e tool C++ Windows. npm install, cargo test --manifest-path src-tauri/Cargo.toml, npm run dev. Ogni invocazione aggiunge una nota e salva JSON nello spazio app it.atlas.tauri.tasks. File malformato interrompe l’avvio invece di sovrascriverlo. La risposta mostra tutte le note; i test Rust coprono validazione/ID/immutabilità, non la WebView.\n'
    book.add('progetto-note','Progetto completo: note Tauri con persistenza nativa','Validare note nel backend Rust e pubblicare il nuovo stato solo dopo un salvataggio riuscito nello spazio app.',project,project=True,section='Inizializzazione',commands='npm install\ncargo test --manifest-path src-tauri/Cargo.toml\nnpm run dev',explanation='## Dati e stato\nIl comando demo accetta soltanto un titolo. Un Mutex serializza modifica e scrittura; il modello conserva la lista precedente finché la sostituzione del file temporaneo non riesce. All’avvio viene letto notes.json dal percorso dell’app e un errore non viene convertito in un archivio vuoto.\n\n## Test e uso\nEsegui cargo test per vuoto, lunghezza e ID/immutabilità. Aggiungi due note nella finestra, chiudi e riapri; aggiungendone una terza la risposta deve contenere anche le precedenti. Il frontend mostra JSON come testo e non interpreta titoli come HTML. La prova della persistenza richiede l’app reale e non èimplicita nei test del modello.',expected='Tre test Rust passano; l’app conserva note dopo riavvio quando viene provata sulla piattaforma prevista.',tags=['tauri','project','JSON','Mutex','persistence','test'])
    assert len(book.recipes)==25;save_book(book)

if __name__=='__main__':build_all()
